using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;

namespace FlightGuard;
public static class VoiceTests
{
    private static void Check(bool condition){if(!condition)throw new Exception("Voice feature regression");}
    private static void Reject(Action a){try{a();}catch{return;}throw new Exception("Invalid input accepted");}
    private static string Temp(){string p=Path.Combine(Path.GetTempPath(),"FlightGuard-voice-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(p);return p;}
    private static byte[] Wave(int frequency=500){using var s=new MemoryStream();using var w=new BinaryWriter(s);int samples=4000;w.Write(Encoding.ASCII.GetBytes("RIFF"));w.Write(36+samples*2);w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(8000);w.Write(16000);w.Write((short)2);w.Write((short)16);w.Write(Encoding.ASCII.GetBytes("data"));w.Write(samples*2);for(int i=0;i<samples;i++)w.Write((short)(Math.Sin(i*frequency*Math.PI*2/8000)*10000));return s.ToArray();}
    private static void Put(string root,string profile,string cue,byte[]? wav=null){string folder=Path.Combine(root,"Sounds",profile);Directory.CreateDirectory(folder);File.WriteAllBytes(Path.Combine(folder,cue+".wav"),wav??Wave());}
    public static void Run(Action<string,Action> test){
        test("GPWS crew and cabin voices route independently",()=>{var s=new Settings{Voices=new(){GpwsVoice="Boeing 787",CrewVoice="Shared Crew",CabinVoice="Shared Cabin"}};Check(VoiceRouting.Requested(s,"Boeing 757",Catalog.Get("pull-up"))=="Boeing 787");Check(VoiceRouting.Requested(s,"Boeing 757",Catalog.Get("rotate"))=="Shared Crew");Check(VoiceRouting.Requested(s,"Boeing 757",Catalog.Get("safety-briefing"))=="Shared Cabin");});
        test("Voice paths remain confined to listed profiles",()=>Reject(()=>new Settings{Voices=new(){GpwsVoice="../../outside"}}.Validate()));
        test("Automatic missing model warnings retain an audible labelled fallback",()=>{string root=Temp();Put(root,"Generic","pull-up");Check(VoiceRouting.Resolve(root,new(),"Boeing 757",Catalog.Get("pull-up"))!.Contains("Generic"));});
        test("A220 automatic route does not silently select an A320 voice",()=>{string root=Temp();Put(root,"Airbus A320 family","pull-up");Put(root,"Generic","pull-up");Check(VoiceRouting.Resolve(root,new(),"Airbus A220",Catalog.Get("pull-up"))!.Contains("Generic"));});
        test("A/B preview ignores live override and resolves selected model",()=>{string root=Temp();Put(root,"Boeing 757","v1");Put(root,"Boeing 787","v1");var s=new Settings{Voices=new(){CrewVoice="Boeing 787"}};Check(VoiceRouting.Resolve(root,s,"Boeing 757",Catalog.Get("v1"))!.Contains("787"));Check(VoiceRouting.Resolve(root,s,"Boeing 757",Catalog.Get("v1"),true)!.Contains("757"));});
        test("Independent levels preserve main and cabin volume scaling",()=>{var s=new Settings{Volume=80,Voices=new(){GpwsVolume=100,CrewVolume=50},Cabin=new(){Volume=25}};Check(VoiceRouting.Volume(s,Catalog.Get("pull-up"))==80);Check(VoiceRouting.Volume(s,Catalog.Get("rotate"))==40);Check(VoiceRouting.Volume(s,Catalog.Get("safety-briefing"))==20);});
        test("Height schedules reject unknown values and retain descending unique heights",()=>{Check(VoiceOptions.ParseHeights("50, 100,50,5").SequenceEqual(new[]{100,50,5}));Reject(()=>VoiceOptions.ParseHeights("999"));Reject(()=>VoiceOptions.ParseHeights(""));});
        test("Suggested aircraft schedule keeps A220 separate and enables A320 five feet",()=>{Check(VoiceOptions.Suggested("A320").Contains(5));Check(!VoiceOptions.Suggested("A220-300").Contains(5));Check(!VoiceOptions.Suggested("757-200").Contains(5));});
        test("Custom five-foot height callout fires once on approach",()=>{var s=new Settings{Warnings=false,Minimums=0,Voices=new(){HeightMode="Custom",CustomHeights="5"}};var engine=new WarningEngine();var t=DateTime.UtcNow;var f=new Frame{Aircraft="A320",Time=t,Agl=7,Msl=107,Vs=-200,Ias=140,Ground=false};engine.Update(f,s,"Airbus",false);var cues=engine.Update(f with{Time=t.AddSeconds(.5),Agl=4,Msl=104},s,"Airbus",false);Check(cues.Count(c=>c.Id=="altitude-5")==1);Check(!engine.Update(f with{Time=t.AddSeconds(.7),Agl=3,Msl=103},s,"Airbus",false).Any(c=>c.Id=="altitude-5"));});
        test("Custom height schedule suppresses other configured heights",()=>{var s=new Settings{Warnings=false,Minimums=0,Voices=new(){HeightMode="Custom",CustomHeights="50"}};var e=new WarningEngine();var f=new Frame{Time=DateTime.UtcNow,Aircraft="757-200",Agl=110,Msl=210,Vs=-600};e.Update(f,s,"Boeing",false);Check(!e.Update(f with{Time=f.Time.AddSeconds(1),Agl=90,Msl=190},s,"Boeing",false).Any(c=>c.Group=="Heights"));});
        test("Voice preferences survive per-aircraft storage and copy without shared references",()=>{var a=new Settings{Voices=new(){CrewVoice="Boeing 787",CustomHeights="100,50",HeightMode="Custom"}};var copy=Settings.Copy(a);copy.Voices.CrewVoice="Auto";Check(a.Voices.CrewVoice=="Boeing 787");var store=new AircraftPreferences(Temp());store.Save("757-200",a);Check(store.Load("757-200",new(),new()).Voices.CrewVoice=="Boeing 787");});
        test("Invalid imported audio cannot replace an installed pack",()=>{string root=Temp(),input=Temp();var old=Wave();Put(root,"Boeing 757","v1",old);File.WriteAllBytes(Path.Combine(input,"v1.wav"),Wave(600));File.WriteAllBytes(Path.Combine(input,"rotate.wav"),new byte[900]);Reject(()=>PersonalVoicePacks.Import(input,"Boeing 757",root));Check(File.ReadAllBytes(Path.Combine(root,"Sounds/Boeing 757/v1.wav")).SequenceEqual(old));});
        test("Personal import mapping cannot traverse outside its selected folder",()=>{string input=Temp();File.WriteAllText(Path.Combine(input,"pack.json"),"{\"v1\":\"../outside.wav\"}");Reject(()=>PersonalVoicePacks.Import(input,"Boeing 757",Temp()));});
        test("Personal pack import backs up existing recordings and undo restores exact bytes",()=>{string root=Temp(),input=Temp();var original=Wave();Put(root,"Boeing 757","v1",original);File.WriteAllBytes(Path.Combine(input,"v1.wav"),Wave(600));File.WriteAllText(Path.Combine(input,"pack-info.json"),JsonSerializer.Serialize(new VoicePackInfo("Test","Test author","Test licence")));Check(PersonalVoicePacks.Import(input,"Boeing 757",root)==1);Check(!File.ReadAllBytes(Path.Combine(root,"Sounds/Boeing 757/v1.wav")).SequenceEqual(original));PersonalVoicePacks.Undo("Boeing 757",root);Check(File.ReadAllBytes(Path.Combine(root,"Sounds/Boeing 757/v1.wav")).SequenceEqual(original));Reject(()=>PersonalVoicePacks.Undo("Boeing 757",root));});
        test("Undo of a first import removes only the newly created model folder",()=>{string root=Temp(),input=Temp();File.WriteAllBytes(Path.Combine(input,"v1.wav"),Wave());PersonalVoicePacks.Import(input,"Boeing 777",root);PersonalVoicePacks.Undo("Boeing 777",root);Check(!Directory.Exists(Path.Combine(root,"Sounds/Boeing 777")));});
        test("Voice inventory exposes missing fallback provenance duration and original hashes",()=>{string root=Temp();Put(root,"Generic","pull-up");var row=new VoiceInventory(root).Inspect(new(),"Boeing 757",Catalog.Get("pull-up"));Check(row.Coverage=="Shared fallback"&&row.Duration>0&&row.Sha256.Length==64&&row.License=="Unknown");Check(new VoiceInventory(root).Inspect(new(),"Boeing 757",Catalog.Get("rotate")).Coverage=="Missing");});
        test("Modified imported clips do not inherit the upstream licence from stale provenance",()=>{string root=Temp();Put(root,"Boeing 757","v1");File.WriteAllText(Path.Combine(root,"sound-provenance.json"),"[{\"family\":\"Boeing 757\",\"cue\":\"v1\",\"sha256\":\"old\",\"license\":\"Not applicable\"}]");File.WriteAllText(Path.Combine(root,"Sounds/Boeing 757/pack-info.json"),JsonSerializer.Serialize(new VoicePackInfo(License:"Personal source")));Check(new VoiceInventory(root).Inspect(new(),"Boeing 757",Catalog.Get("v1")).License=="Personal source");});
        test("Pack templates preserve existing files and export all cue mappings",()=>{string folder=Temp();PersonalVoicePacks.Template(folder,"Boeing 757");Check(JsonSerializer.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(Path.Combine(folder,"pack.json")))!.Count==Catalog.All.Count);Reject(()=>PersonalVoicePacks.Template(folder,"Boeing 757"));});
        test("Quiet final clears queued routine crew while preserving critical calls",()=>{var q=new CueQueue();var t=DateTime.UtcNow;q.Offer(new[]{Catalog.Get("v1"),Catalog.Get("autopilot-disconnect"),Catalog.Get("gear-down")},t,null,default);Check(q.Count==3);q.CancelRoutineCrew();Check(q.Count==2);Check(q.Next(t)!.Cue.Id=="v1");Check(q.Next(t)!.Cue.Id=="autopilot-disconnect");});
    }
}
